func workspaceGraphImportCrossEdges(indexes []workspaceRepoGraphIndex, limit int) []workspaceGraphCrossEdge {
	var edges []workspaceGraphCrossEdge
	for _, fromRepo := range indexes {
		for _, imp := range fromRepo.Imports {
