1501	func workspaceRepoImportPrefixes(repoKey string) []string {
1502		repoKey = strings.Trim(strings.TrimSpace(filepath.ToSlash(repoKey)), "/")
1503		parts := strings.Split(repoKey, "/")
1504		prefixes := []string{repoKey}
1505		if len(parts) >= 3 && parts[0] == "gh" {
1506			ownerRepo := strings.Join(parts[1:3], "/")
1507			prefixes = append(prefixes, "github.com/"+ownerRepo, ownerRepo, "@"+ownerRepo)
1508			if len(parts) >= 5 && parts[3] == "packages" {
1509				pkg := strings.Join(parts[4:], "/")
1510				prefixes = append(prefixes, "github.com/"+ownerRepo+"/packages/"+pkg, ownerRepo+"/packages/"+pkg, "@"+parts[1]+"/"+pkg)
1511				for _, alias := range workspacePackageImportAliases("gh", pkg) {
1512					prefixes = append(prefixes, "github.com/"+ownerRepo+"/packages/"+alias, ownerRepo+"/packages/"+alias, "@"+parts[1]+"/"+alias)
1513				}
1514			}
1515		}
1516		if len(parts) >= 2 {
1517			switch parts[0] {
1518			case "cargo", "composer", "gem", "gomod", "npm", "nuget", "pypi":
1519				pkg := strings.Join(parts[1:], "/")
1520				prefixes = append(prefixes, pkg)
1521				prefixes = append(prefixes, workspacePackageImportAliases(parts[0], pkg)...)
1522			case "maven":
1523				groupArtifact := strings.Join(parts[1:], "/")
1524				prefixes = append(prefixes, groupArtifact, strings.ReplaceAll(groupArtifact, "/", "."))
1525			}
1526		}
1527		sort.Slice(prefixes, func(i, j int) bool {
1528			if len(prefixes[i]) != len(prefixes[j]) {
1529				return len(prefixes[i]) > len(prefixes[j])
1530			}
1531			return prefixes[i] < prefixes[j]
1532		})
1533		deduped := prefixes[:0]
1534		seen := map[string]bool{}
1535		for _, prefix := range prefixes {
1536			if prefix == "" || seen[prefix] {
1537				continue
1538			}
