	repoDir := t.TempDir()
	if err := os.MkdirAll(filepath.Join(repoDir, "internal/auth"), 0o755); err != nil {
		t.Fatal(err)
	}
	lines := make([]string, 25)
	for i := range lines {
		lines[i] = fmt.Sprintf("// line %02d", i+1)
